import{_ as t,o,c as d,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"FR 3.7.2 — View AI Trend Knowledge Graph","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-2-view-ai-trend-knowledge-graph/spec.md","filePath":"feature/srs/06-ai-features/3-7-2-view-ai-trend-knowledge-graph/spec.md"}'),r={name:"feature/srs/06-ai-features/3-7-2-view-ai-trend-knowledge-graph/spec.md"};function n(c,e,i,s,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-2-—-view-ai-trend-knowledge-graph" tabindex="-1">FR 3.7.2 — View AI Trend Knowledge Graph <a class="header-anchor" href="#fr-3-7-2-—-view-ai-trend-knowledge-graph" aria-label="Permalink to &quot;FR 3.7.2 — View AI Trend Knowledge Graph&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.2</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-089</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View AI Trend Knowledge Graph</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Admin</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-45</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG02</code>, <code>MSG03</code>, <code>MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Provide an interactive Neo4j-backed Trend Knowledge Graph explorer (<code>/workspaces/:workspaceId/trends</code> &amp; <code>/admin?view=trend-graph</code>) that visualizes multi-platform trend topology across <code>Trend</code>, <code>Topic</code>, <code>Keyword</code>, <code>Hashtag</code>, <code>Entity</code>, and <code>PlatformSource</code> nodes along with <code>CO_OCCURS_WITH</code>, <code>BELONGS_TO_CATEGORY</code>, and <code>MENTIONED_IN</code> relationships (<code>BR-45</code>). Content teams (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>) inspect semantic clusters, momentum scores, and brand-fit context before drafting content, while <code>Admin</code> audits global ingestion graph health.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, or <code>Admin</code>, I want to explore the AI Trend Knowledge Graph with bounded neighborhood expansion, node inspection, and category/platform filtering so that I can trace how viral keywords, hashtags, and named entities connect in real time without exposing cross-tenant workspace brand context.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Role &amp; Scope Enforcement:</strong> Authenticated <code>Owner</code>, <code>Manager</code>, and <code>Creator</code> members of a Workspace can inspect the Workspace Trend Explorer (<code>/api/v1/workspaces/{workspaceId}/trends</code>, <code>/matrix</code>, <code>/history</code>), while <code>Admin</code> can also query global graph inspection endpoints (<code>/api/v1/admin/ai/trend-graph/overview</code>, <code>/neighborhood</code>, <code>/nodes</code>, <code>/expand</code>). Unauthorized callers receive <code>403 FORBIDDEN</code> (<code>MSG07</code>).</li><li><strong>Bounded Graph Traversal (<code>BR-45</code>):</strong> Neighborhood expansion strictly clamps hop depth (<code>depth ∈ [1, 2]</code>) and neighbor fan-out (<code>limit &lt;= 100</code> nodes, <code>&lt;= 250</code> edges) to prevent Neo4j Cypher supernode explosions.</li><li><strong>Node Inspector &amp; Source Provenance:</strong> Selecting any node displays its normalized label, node type (<code>Trend</code>, <code>Topic</code>, <code>Hashtag</code>, <code>Entity</code>), virality/momentum score, first-seen/last-seen timestamps, and anonymized source post evidence across supported trend sources.</li><li><strong>Action Bridge to Caption Generation:</strong> Clicking &quot;Use Trend in Caption&quot; from the Inspector pre-populates <code>trendId</code> and Neo4j graph context into FR 3.7.6 (<code>Generate Caption</code>).</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All graph controls, node type badges, filter pills, empty states, and inspector labels use key-parallel entries in <code>src/i18n/locales/{vi,en}/trends.json</code> and <code>admin.json</code> (and <code>tr(&#39;trends.*&#39;)</code> on Mobile) with zero hardcoded UI strings.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> Force-directed canvas (<code>TrendGraphCanvas.tsx</code>, <code>TrendGraphScene.tsx</code>), node category colors, edge opacity, and inspector sidebars adapt seamlessly between Light and Dark themes via semantic CSS variables and <code>dark:</code> variants.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces:</strong> <code>pages/workspace-trends/index.tsx</code> (<code>TrendViews.tsx</code>, <code>TrendHistoryCharts.tsx</code>) and <code>pages/admin/components/AdminTrendGraphPanel.tsx</code> (<code>TrendGraphWorkspace.tsx</code>, <code>TrendGraphCanvas.tsx</code>, <code>TrendGraphInspector.tsx</code>, <code>TrendGraphSearch.tsx</code>).</li><li><strong>Mobile Surface:</strong> <code>src/screens/more/SocialTrendsScreen.tsx</code> using <code>useAppPreferences().palette</code>.</li><li><strong>UI States:</strong><ul><li><strong>Loading:</strong> Shimmer graph skeleton (<code>TrendSkeleton.tsx</code>) while fetching initial overview root and top-weighted edges.</li><li><strong>Interactive Ready:</strong> Zoom/pan canvas, search autocomplete, node click -&gt; side inspector + incremental <code>GET /expand</code> fetch.</li><li><strong>Empty:</strong> Localized empty state when no graph nodes match the selected date window or category filter.</li><li><strong>Degraded / Neo4j Unavailable:</strong> Non-blocking error banner (<code>MSG03</code>) with retry button; cached summary list remains readable.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Caller Role</th><th style="text-align:left;">Upstream Handler</th><th style="text-align:left;">Response</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/trends</code></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td><td style="text-align:left;"><code>WorkspaceTrendController</code> -&gt; <code>ai-service</code> <code>/api/v1/ai/trends/explore</code></td><td style="text-align:left;"><code>ApiResponse&lt;WorkspaceTrendListResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/trends/matrix</code></td><td style="text-align:left;"><code>Owner, Manager, Creator</code></td><td style="text-align:left;"><code>WorkspaceTrendController.matrix()</code> -&gt; <code>workspace_trends.py</code></td><td style="text-align:left;"><code>ApiResponse&lt;TrendMatrixResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/admin/ai/trend-graph/overview</code></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;"><code>AdminTrendGraphController</code> -&gt; <code>trend_graph.py</code> <code>GET /ai/graph/explorer/overview</code></td><td style="text-align:left;"><code>ApiResponse&lt;TrendGraphOverviewResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/admin/ai/trend-graph/neighborhood</code></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;"><code>AdminTrendGraphController</code> -&gt; <code>trend_graph.py</code> <code>GET /ai/graph/explorer/neighborhood</code></td><td style="text-align:left;"><code>ApiResponse&lt;TrendGraphNeighborhoodResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/admin/ai/trend-graph/expand</code></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;"><code>AdminTrendGraphController</code> -&gt; <code>trend_graph.py</code> <code>GET /ai/graph/explorer/expand</code></td><td style="text-align:left;"><code>ApiResponse&lt;TrendGraphExpandResponse&gt;</code></td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>NODE_NOT_FOUND</code> (<code>404</code>, <code>MSG01</code>): Seed <code>nodeId</code> or <code>trendId</code> was evicted or never ingested into Neo4j.</li><li><code>INVALID_GRAPH_QUERY</code> (<code>400</code>, <code>MSG02</code>): Caller passes <code>limit &gt; 100</code> or unsupported node type filter.</li><li><code>GRAPH_STORE_UNAVAILABLE</code> (<code>503</code>, <code>MSG03</code>): Neo4j Bolt driver timeout or circuit breaker open (<code>app/utils/circuit_breaker.py</code>); returns structured fallback error without crashing worker pool.</li><li><strong>Supernode Protection:</strong> High-degree hub nodes (e.g., <code>#vietnam</code>, <code>#trending</code>) sort neighbors by <code>co_occurrence_weight DESC, updated_at DESC</code> before applying <code>LIMIT</code>.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-1-view-trending-topics-suggestions/spec.html">FR 3.7.1 — View Trending Topics Suggestions</a> · <a href="./../3-7-6-generate-caption/spec.html">FR 3.7.6 — Generate Caption</a> · <a href="./../3-7-13-crawl-schedule-config/spec.html">FR 3.7.13 — Crawl Schedule Config</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/05-ai-rag-and-crawler/neo4j-trend-knowledge-graph/spec.html"><code>neo4j-trend-knowledge-graph</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Parameterized Cypher queries verified in <code>trend_graph_service.py</code>, Business proxy authorization verified, Web &amp; Mobile graph/explorer views localized in <code>vi</code> + <code>en</code> and verified in Light/Dark themes, all test cases in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> Manual editing of Neo4j nodes from the UI; social publishing outside the 4 canonical platforms (Facebook, Instagram, TikTok, Threads).</li></ul>',19)])])}const f=t(r,[["render",n]]);export{h as __pageData,f as default};
